</section></div></form>
<script>
const cart={};const rows=document.querySelector('#basket-rows');const totalEl=document.querySelector('#total');const paid=document.querySelector('#paid');const submit=document.querySelector('#submit-sale');
document.querySelectorAll('.add').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.id;cart[id]??={id,name:button.dataset.name,price:Number(button.dataset.price),qty:0,stock:Number(button.dataset.stock)};if(cart[id].qty<cart[id].stock)cart[id].qty++;renderCart()}));
function renderCart(){let total=0;rows.replaceChildren();const entries=Object.values(cart).filter(item=>item.qty>0);if(!entries.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.className='empty-state';td.textContent='ยังไม่มีสินค้าในตะกร้า';tr.append(td);rows.append(tr)}entries.forEach(item=>{const subtotal=item.price*item.qty;total+=subtotal;const tr=document.createElement('tr'),name=document.createElement('td'),qty=document.createElement('td'),sum=document.createElement('td'),controls=document.createElement('div'),minus=document.createElement('button'),count=document.createElement('span'),plus=document.createElement('button');name.textContent=item.name;controls.className='qty-control';minus.type=plus.type='button';minus.className=plus.className='small secondary';minus.textContent='−';plus.textContent='+';count.textContent=item.qty;minus.setAttribute('aria-label','ลดจำนวน '+item.name);plus.setAttribute('aria-label','เพิ่มจำนวน '+item.name);minus.onclick=()=>{item.qty--;renderCart()};plus.onclick=()=>{if(item.qty<item.stock)item.qty++;renderCart()};controls.append(minus,count,plus);qty.append(controls);sum.className='text-right';sum.textContent=subtotal.toFixed(2);tr.append(name,qty,sum);rows.append(tr)});totalEl.textContent=total.toFixed(2);paid.min=total.toFixed(2);paid.value=total?total.toFixed(2):'';submit.disabled=!entries.length}
document.querySelector('#product-search').addEventListener('input',event=>{const term=event.target.value.trim().toLocaleLowerCase();let visible=0;document.querySelectorAll('.add').forEach(button=>{const match=button.dataset.name.toLocaleLowerCase().includes(term);button.hidden=!match;if(match)visible++});document.querySelector('#no-products').hidden=visible>0});document.querySelector('#clear-cart').onclick=()=>{Object.values(cart).forEach(item=>item.qty=0);renderCart()};
document.querySelector('#sale').addEventListener('submit',event=>{if(!Object.values(cart).some(item=>item.qty>0)){event.preventDefault();return}event.preventDefault();document.querySelectorAll('[data-line]').forEach(input=>input.remove());Object.values(cart).filter(item=>item.qty>0).forEach((item,index)=>[['id',item.id],['qty',item.qty]].forEach(([key,value])=>{const input=document.createElement('input');input.type='hidden';input.name='items['+index+']['+key+']';input.value=value;input.dataset.line='1';event.currentTarget.append(input)}));event.currentTarget.submit()});
</script>
